-- St. Louis 311 closure classes (N2, 13-14 Oct 2026). Generated by scripts/night/N2/08_sql_classifier.py.
-- Classes: done, handed_off, converted, no_action, info_other, blank. Rule table drafted by an AI model; review it.
CREATE OR REPLACE TABLE closure_text_class (text_norm VARCHAR PRIMARY KEY, class VARCHAR, rule VARCHAR);
CREATE OR REPLACE TABLE closure_type_override (problemcode VARCHAR, text_norm VARCHAR, class VARCHAR, rule VARCHAR);
CREATE OR REPLACE MACRO closure_class(pc, t) AS CASE
  WHEN lower(trim(regexp_replace(coalesce(t, ''), '\s+', ' ', 'g'))) = '' THEN 'blank'
  ELSE coalesce(
    (SELECT o.class FROM closure_type_override o WHERE o.problemcode = pc AND o.text_norm = lower(trim(regexp_replace(coalesce(t, ''), '\s+', ' ', 'g')))),
    (SELECT c.class FROM closure_text_class c WHERE c.text_norm = lower(trim(regexp_replace(coalesce(t, ''), '\s+', ' ', 'g')))),
    CASE WHEN starts_with(lower(trim(regexp_replace(coalesce(t, ''), '\s+', ' ', 'g'))), 'more information is needed.') THEN 'info_other' ELSE 'info_other' END)
  END;
CREATE OR REPLACE MACRO closure_rule(pc, t) AS CASE
  WHEN lower(trim(regexp_replace(coalesce(t, ''), '\s+', ' ', 'g'))) = '' THEN 'blank:no_text'
  ELSE coalesce(
    (SELECT o.rule FROM closure_type_override o WHERE o.problemcode = pc AND o.text_norm = lower(trim(regexp_replace(coalesce(t, ''), '\s+', ' ', 'g')))),
    (SELECT c.rule FROM closure_text_class c WHERE c.text_norm = lower(trim(regexp_replace(coalesce(t, ''), '\s+', ' ', 'g')))),
    CASE WHEN starts_with(lower(trim(regexp_replace(coalesce(t, ''), '\s+', ' ', 'g'))), 'more information is needed.') THEN 'info_other:need_info' ELSE 'info_other:unlisted (not yet reviewed)' END)
  END;
